```kotlin
import java.util.Scanner

fun main() {
    val br = System.`in`.bufferedReader()
    val (hpY, atkY, defY) = br.readLine().trim().split(" ").map { it.toInt() }
    val (hpM, atkM, defM) = br.readLine().trim().split(" ").map { it.toInt() }
    val (h, a, d) = br.readLine().trim().split(" ").map { it.toInt() }

    var minCost = Long.MAX_VALUE

    val maxAddAtk = defM + hpM  // enough to kill in one hit
    val maxAddDef = atkM        // enough to negate all damage

    for (addAtk in 0..maxAddAtk) {
        val dmgToMonster = atkY + addAtk - defM
        if (dmgToMonster <= 0) continue
        val turns = (hpM + dmgToMonster - 1) / dmgToMonster

        for (addDef in 0..maxAddDef) {
            val dmgToYang = maxOf(0, atkM - (defY + addDef))
            val totalDamage = turns.toLong() * dmgToYang.toLong()

            val neededHp = if (totalDamage >= hpY) {
                totalDamage - hpY + 1
            } else {
                0L
            }

            val cost = neededHp * h + addAtk.toLong() * a + addDef.toLong() * d
            if (cost < minCost) {
                minCost = cost
            }
        }
    }

    println(minCost)
}
